use lapis_app_protocol::turns::*;
use ts_rs::{Config, TS};

pub(super) fn declarations(config: &Config) -> [String; 9] {
    [
        TurnOptions::decl(config),
        TurnTarget::decl(config),
        TurnContinuation::decl(config),
        TurnInput::decl(config),
        TurnPhase::decl(config),
        TurnRecord::decl(config),
        TurnSummary::decl(config),
        TurnCommand::decl(config),
        TurnValue::decl(config),
    ]
}
pub(super) fn typescript(config: &Config) -> String {
    format!(
        "// Generated by pnpm protocol:generate. Do not edit.\n{}\n",
        declarations(config)
            .iter()
            .map(|item| format!("export {item}"))
            .collect::<Vec<_>>()
            .join("\n")
    )
}
